import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Corpus & .frc bundles","description":"","frontmatter":{},"headers":[],"relativePath":"corpus/index.md","filePath":"corpus/index.md"}'),n={name:"corpus/index.md"};function l(o,e,d,p,c,r){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="corpus-frc-bundles" tabindex="-1">Corpus &amp; .frc bundles <a class="header-anchor" href="#corpus-frc-bundles" aria-label="Permalink to &quot;Corpus &amp; .frc bundles&quot;">​</a></h1><p>The corpus is a set of <strong>labelled example families</strong>. Each family contains at least one <em>positive</em> (vulnerable) example and one <em>negative</em> (fixed) example. The bundler replays each family through the engine, diffs the two variants, learns facts that distinguish them, then verifies those facts against every other family before publishing them into a <code>.frc</code> bundle.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mycorpus/</span></span>
<span class="line"><span>├── bug_classes.json                  # class registry the lint checks against</span></span>
<span class="line"><span>└── ts/inj.sql/ts_sqli/</span></span>
<span class="line"><span>    ├── ts_sqli_positive.ts           # [frensense] metadata block at the top</span></span>
<span class="line"><span>    ├── ts_sqli_negative.ts           # fixed version, starts with &quot;SAFE:&quot;</span></span>
<span class="line"><span>    ├── ts_sqli_heldout_positive.ts   # blind pair: never read by the bundler</span></span>
<span class="line"><span>    └── ts_sqli_heldout_negative.ts</span></span></code></pre></div><p>The <code>&lt;family&gt;_positive.&lt;ext&gt;</code> / <code>&lt;family&gt;_negative.&lt;ext&gt;</code> infix is what makes a family; a directory with <code>positive.ts</code> and <code>negative.ts</code> groups <strong>zero</strong> families. Supported extensions: <code>ts</code>, <code>tsx</code>, <code>js</code>, <code>jsx</code>, <code>py</code>, <code>go</code>, <code>rs</code>, <code>c</code>, <code>cpp</code>, <code>h</code>, <code>hpp</code>.</p><h2 id="lint-build-inspect" tabindex="-1">Lint, build, inspect <a class="header-anchor" href="#lint-build-inspect" aria-label="Permalink to &quot;Lint, build, inspect&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Pre-flight: metadata, layout, provenance, diversity, teachability.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mycorpus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --strict</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Compile the families into a bundle.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mycorpus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my.frc</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Read what was actually published.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my.frc</span></span></code></pre></div><p><code>frensense lint</code> never scans target code unless you ask it to, and it refuses the mistakes the replay gate cannot see: a mislabelled class, copied families, placeholder advisory prose, and a pair that would teach nothing (<code>PU004</code>). <code>frensense bundle</code> is the current spelling of the old <code>frensense-bundler</code> invocation that took a corpus and an output path.</p><h2 id="use-the-bundle" tabindex="-1">Use the bundle <a class="header-anchor" href="#use-the-bundle" aria-label="Permalink to &quot;Use the bundle&quot;">​</a></h2><p>Place the output at the root of the scanned project as <code>frensense-corpus.frc</code> (auto-discovered), pass it with <code>-b</code> / <code>--bundle</code> / <code>--corpus-bundle</code>, or set <code>FRENSENSE_CORPUS_BUNDLE</code> for MCP and LSP.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/corpus/authoring">Authoring guide</a> - the full contract: required metadata, the nine fact shapes a family can teach, held-out pairs, the lint codes, verified command output, and a migration checklist for families written against the old guide.</li></ul>`,11)])])}const k=s(n,[["render",l]]);export{u as __pageData,k as default};
